// Service worker for animalcrimebureau.org, generated by tools/build.mjs.
// Pages are fetched from the network first, so corrections reach readers at
// once, and fall back to the saved copy without a connection. Every page of
// the site is saved when the worker installs.
const VERSION = '__VERSION__';
const CACHE = 'acb-' + VERSION;
const PAGES = __PAGES__;
const ASSETS = __ASSETS__;
// Only this site's own sections; other projects on the domain, such as /law-xray/, are left alone.
const SECTIONS = new Set(['', 'ar', 'law', 'register', 'publications', 'about', 'offline.html']);
const WAIT = 3000;

self.addEventListener('install', event => {
  event.waitUntil(caches.open(CACHE).then(cache => cache.addAll(PAGES.concat(ASSETS))).then(() => self.skipWaiting()));
});

self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k.startsWith('acb-') && k !== CACHE).map(k => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', event => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  if (request.mode === 'navigate' && SECTIONS.has(url.pathname.split('/')[1])) {
    event.respondWith(page(event, url));
  } else if (url.pathname.startsWith('/assets/')) {
    event.respondWith(asset(request));
  }
});

async function page(event, url) {
  const cache = await caches.open(CACHE);
  const key = url.origin + url.pathname;
  const network = fetch(event.request).then(response => {
    if (response.ok && response.type === 'basic') cache.put(key, response.clone());
    return response;
  });
  event.waitUntil(network.catch(() => {}));
  const saved = await cache.match(key);
  if (!saved) return network.catch(async () => (await cache.match('/offline.html')) || Response.error());
  // A slow connection gets the saved page after a short wait; the fresh one is saved for next time.
  const late = new Promise(resolve => setTimeout(() => resolve(saved), WAIT));
  return Promise.race([network.catch(() => saved), late]);
}

async function asset(request) {
  const cache = await caches.open(CACHE);
  const saved = await cache.match(request);
  if (saved) return saved;
  const response = await fetch(request);
  if (response.ok && response.type === 'basic') cache.put(request, response.clone());
  return response;
}
